<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { AlertTriangle, CalendarClock, FileImage, FolderKanban, Plus, ShieldCheck } from '@lucide/vue'; import { api, type CampaignSummary, type Dashboard } from '../lib/api'; import { useSessionStore } from '../stores/session'
const session = useSessionStore(); const router = useRouter(); const stats = ref<Dashboard|null>(null); const campaigns = ref<CampaignSummary[]>([]); const error = ref('')
async function load(){try{[stats.value,campaigns.value]=await Promise.all([api.dashboard(),api.campaigns(session.brandId)])}catch(e){error.value=e instanceof Error?e.message:'載入失敗'}}
onMounted(load)
</script>
<template><div class="page-stack"><section class="welcome-row"><div><p class="eyebrow">TODAY'S WORKSPACE</p><h2>早安，{{ session.user?.displayName }}</h2><p>掌握待審內容與接下來的發布節奏。</p></div><button class="button primary" @click="router.push('/campaigns')"><Plus :size="17"/>建立內容</button></section><p v-if="error" class="form-error">{{error}}</p><section class="metric-grid"><article><span class="metric-icon coral"><FolderKanban/></span><div><small>進行中企劃</small><strong>{{stats?.campaignCount??'—'}}</strong><p>{{stats?.postCount??0}} 篇內容</p></div></article><article><span class="metric-icon violet"><ShieldCheck/></span><div><small>待處理審核</small><strong>{{stats?.reviewCount??'—'}}</strong><p>需要團隊確認</p></div></article><article><span class="metric-icon blue"><CalendarClock/></span><div><small>已排程</small><strong>{{stats?.scheduledCount??'—'}}</strong><p>等待模擬發布</p></div></article><article><span class="metric-icon amber"><AlertTriangle/></span><div><small>發布異常</small><strong>{{stats?.failedCount??'—'}}</strong><p>可重新執行</p></div></article></section><div class="overview-grid"><section class="panel"><div class="panel-head"><div><p class="eyebrow">RECENT CAMPAIGNS</p><h3>最近企劃</h3></div><RouterLink to="/campaigns">查看全部</RouterLink></div><div v-if="campaigns.length" class="compact-list"><button v-for="item in campaigns.slice(0,5)" :key="item.id" @click="router.push(`/campaigns/${item.id}`)"><span class="list-icon"><FolderKanban :size="18"/></span><span><strong>{{item.name}}</strong><small>{{item.brandName}} · {{item.postCount}} 篇內容</small></span><i class="status-chip">{{item.status}}</i></button></div><div v-else class="empty-block"><FolderKanban/><p>尚未建立企劃</p></div></section><section class="panel"><div class="panel-head"><div><p class="eyebrow">UPCOMING</p><h3>近期排程</h3></div><RouterLink to="/calendar">開啟日曆</RouterLink></div><div v-if="stats?.upcoming.length" class="timeline-list"><article v-for="item in stats.upcoming" :key="item.id"><span>{{new Date(item.scheduledAt).toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'})}}</span><div><strong>{{item.postTitle}}</strong><small>{{item.platform}} · {{new Date(item.scheduledAt).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})}}</small></div></article></div><div v-else class="empty-block"><FileImage/><p>目前沒有近期排程</p></div></section></div></div></template>
